                    { -8, "<div style='font-family: sans-serif; padding: 20px; border: 1px solid #eee; border-radius: 10px; max-width: 600px;'><h2 style='color: #27ae60;'>Link Request Accepted</h2><p>Hello <strong>{{FullName}}</strong>,</p><p>Your family link request to <strong>{{TargetName}}</strong> has been accepted.</p><p>You are now connected in the {{OrgShortName}} network.</p></div>", 0, "FAMILY_LINK_ACCEPTED", "Family link acceptance confirmation", new DateTime(2026, 9, 7, 19, 37, 2, 68, DateTimeKind.Utc).AddTicks(426), "Family Link Request Accepted", "['FullName', 'TargetName']" },
                    { -7, "<div style='font-family: sans-serif; padding: 20px; border: 1px solid #eee; border-radius: 10px; max-width: 600px;'><h2 style='color: #2c3e50;'>Family Link Request</h2><p>Hello <strong>{{FullName}}</strong>,</p><p><strong>{{RequesterName}}</strong> has requested to link their account with yours as a <strong>{{Relationship}}</strong>.</p><div style='text-align: center; margin: 30px 0;'><a href='{{ProfileUrl}}' style='background: #c5a059; color: #fff; padding: 12px 30px; text-decoration: none; border-radius: 8px; font-weight: bold; border: 1px solid #c5a059;'>Review Request</a></div><p>Please log in to your profile to accept or decline this request.</p></div>", 0, "FAMILY_LINK_REQUEST", "Family link request email", new DateTime(2026, 9, 7, 19, 37, 2, 68, DateTimeKind.Utc).AddTicks(349), "New Family Link Request from {{RequesterName}}", "['FullName', 'RequesterName', 'Relationship', 'ProfileUrl']" },
